import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game'), shell=document.querySelector('#game-shell');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a9c8c4'); scene.fog=new THREE.Fog('#a9c8c4',48,135);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,220);
scene.add(new THREE.HemisphereLight('#e5f5ec','#62775c',2.05));
const sun=new THREE.DirectionalLight('#fff0d3',2.6); sun.position.set(-25,38,18); scene.add(sun);
const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={grass:mat('#779b6b'),sand:mat('#c2b47d'),trunk:mat('#75513a'),leaf:mat('#426b4c'),leaf2:mat('#698e56'),stone:mat('#818a78'),roof:mat('#bd7657'),wall:mat('#d1bd94'),blue:mat('#315c69'),lime:mat('#d8f36a'),enemy:mat('#bf5548'),enemy2:mat('#e2aa79'),dark:mat('#263b3d'),gun:mat('#222d2d'),crate:mat('#c29347'),water:mat('#5f9a9c')};
const ground=new THREE.Mesh(new THREE.CircleGeometry(72,64),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;scene.add(ground);
const sea=new THREE.Mesh(new THREE.CircleGeometry(180,80),mats.water);sea.rotation.x=-Math.PI/2;sea.position.y=-.45;scene.add(sea);
const grid=new THREE.GridHelper(140,46,'#668b69','#668b69');grid.position.y=-.08;grid.material.transparent=true;grid.material.opacity=.13;scene.add(grid);
const rand=(a,b)=>a+Math.random()*(b-a), clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const boxGeo=new THREE.BoxGeometry(1,1,1), sphereGeo=new THREE.SphereGeometry(1,10,8), coneGeo=new THREE.ConeGeometry(1,1,7);
function cube(parent,geo,material,pos,scale){const o=new THREE.Mesh(geo,material);o.position.set(...pos);o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function makeTree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cube(g,boxGeo,mats.trunk,[0,.8*s,0],[.35*s,1.6*s,.35*s]);for(let i=0;i<3;i++){const c=cube(g,coneGeo,i===1?mats.leaf2:mats.leaf,[0,(1.8+i*.55)*s,0],[(1.05-i*.13)*s,1.45*s,(1.05-i*.13)*s]);c.rotation.y=i*.4;}return g;}
function makeRock(x,z,s){const o=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),mats.stone);o.position.set(x,s*.48,z);o.rotation.set(rand(0,.3),rand(0,5),rand(0,.3));o.scale.set(1,rand(.65,1),rand(.8,1.2));scene.add(o);return o;}
function makeHouse(x,z,rot=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);cube(g,boxGeo,mats.wall,[0,1.25,0],[5.3,2.5,4.2]);cube(g,boxGeo,mats.roof,[0,2.75,0],[5.9,.45,4.8]);cube(g,boxGeo,mats.blue,[1.15,1.1,2.12],[.8,1,.08]);cube(g,boxGeo,mats.dark,[-1.3,1.5,2.13],[.8,.7,.08]);cube(g,boxGeo,mats.dark,[0,.65,2.14],[.75,1.3,.09]);return g;}
// Island scenery: wooded ridges, a tiny village, cover and supply caches.
makeHouse(-16,-19,.3);makeHouse(-8,-23,-.2);makeHouse(-22,-25,.1);makeHouse(24,16,.55);makeHouse(30,21,-.3);
for(let i=0;i<70;i++){let x=rand(-60,60),z=rand(-58,58);if(Math.hypot(x,z)<13||((x<-6&&x>-27)&&(z<-16&&z>-30))||((x>22&&z>13)))continue;makeTree(x,z,rand(.65,1.35));}
for(let i=0;i<34;i++){let x=rand(-55,55),z=rand(-55,55);if(Math.hypot(x,z)>9)makeRock(x,z,rand(.35,1.2));}
const loot=[];
for(let i=0;i<7;i++){const a=i/7*Math.PI*2,r=rand(13,40),g=new THREE.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);scene.add(g);cube(g,boxGeo,mats.crate,[0,.45,0],[.9,.9,.9]);cube(g,boxGeo,mat('#e5ca79'),[0,.93,0],[.95,.08,.95]);loot.push({mesh:g,active:true});}
