const pbody=new THREE.Group();player.add(pbody);
cube(pbody,boxGeo,mats.blue,[0,1.08,0],[.75,.95,.43]);cube(pbody,sphereGeo,mat('#d99d72'),[0,1.88,0],[.34,.38,.34]);cube(pbody,boxGeo,mat('#e2bd65'),[0,2.16,0],[.58,.16,.52]);
cube(pbody,boxGeo,mats.dark,[-.22,.38,0],[.25,.62,.3]);cube(pbody,boxGeo,mats.dark,[.22,.38,0],[.25,.62,.3]);
const gun=cube(pbody,boxGeo,mats.gun,[.49,1.14,-.27],[.18,.19,.92]);gun.rotation.x=-.04;cube(pbody,boxGeo,mat('#829276'),[.49,1.2,-.7],[.22,.22,.23]);
const playerRing=new THREE.Mesh(new THREE.RingGeometry(.56,.64,24),new THREE.MeshBasicMaterial({color:0xd8f36a,transparent:true,opacity:.75,side:THREE.DoubleSide}));playerRing.rotation.x=-Math.PI/2;playerRing.position.y=.015;player.add(playerRing);
const enemies=[];
function makeEnemy(x,z,index){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const body=new THREE.Group();g.add(body);const shirt=[mat('#d26e51'),mat('#8e6ab5'),mat('#cf9b4a'),mat('#4b8290')][index%4],skin=mats.enemy2;
